1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
31	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
32	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
36	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
37	    @Mapping(target = "bulkSignupWarning", ignore = true)
38	    @Mapping(target = "capacityWarning", ignore = true)
39	    @Mapping(target = "riskFlag", ignore = true)
40	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derives an owner's age band from the birth date, computed against the registration date
45	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
46	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
47	     * {@code null} when no birth date is present, so the field is omitted from the response.
48	     */
49	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
50	        if (owner == null || owner.getBirthDate() == null) {
51	            return null;
52	        }
53	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
54	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
55	        if (age < 18) {
56	            return OwnerDto.AgeBandEnum.MINOR;
57	        }
58	        if (age < 65) {
59	            return OwnerDto.AgeBandEnum.ADULT;
60	        }
61	        return OwnerDto.AgeBandEnum.SENIOR;
62	    }
63	
64	    /**
65	     * Derives an owner's segment formatted {@code '<TIER>_<AREA>'}. TIER is {@code PREMIUM} when
66	     * the membership level is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
67	     * locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
68	     * Returns {@code null} when the owner is {@code null}.
69	     */
70	    default OwnerDto.OwnerSegmentEnum formatOwnerSegment(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        boolean premium = formatMembershipLevel(owner) >= 3;
75	        String locality = formatLocality(owner);
76	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
77	        if (premium) {
78	            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
79	        }
80	        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
81	    }
82	
83	    /**
84	     * Derives an owner's duplicate-detection identity key as the lower-case SHA-256 hex digest over
85	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} from the stored (already
86	     * E.164-normalized) telephone, lower-cased email and the Soundex code of the last name. A
87	     * {@code null} telephone or email contributes the empty string in its position.
88	     */
89	    default String formatIdentityKey(Owner owner) {
90	        if (owner == null) {
91	            return null;
92	        }
93	        return org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(
94	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
95	    }
96	
97	    /**
98	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
99	     * (non-null and non-blank), otherwise {@code PHONE}.
100	     */
101	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
106	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
107	    }
108	
109	    /**
110	     * Derives an owner's locality (region) from the memberId identity: it is the {@code REGION}
111	     * segment of the {@code '<REGION><FY><HASH8><CHK>'} memberId (everything preceding its
112	     * fixed-length trailing FY, HASH8 and CHK segments). When the memberId is absent it falls back to
113	     * resolving the region directly, preferring the postcode range (NSW 2000-2099, VIC 3000-3099,
114	     * QLD 4000-4099) and then the fixed city-to-region table ({@code Sydney -> NSW},
115	     * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding {@code "UNKNOWN"} when neither
116	     * resolves.
117	     */
118	    default String formatLocality(Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        String region = memberIdRegion(owner.getMemberId());
123	        if (region != null) {
124	            return region;
125	        }
126	        String fromPostcode = regionForPostcode(owner.getPostcode());
127	        if (fromPostcode != null) {
128	            return fromPostcode;
129	        }
130	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
131	            case "Sydney" -> "NSW";
132	            case "Melbourne" -> "VIC";
133	            case "Brisbane" -> "QLD";
134	            default -> "UNKNOWN";
135	        };
136	    }
137	
138	    /**
139	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
140	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
141	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
142	     * so the field is omitted from the response.
143	     */
144	    default String formatTimezone(Owner owner) {
145	        if (owner == null) {
146	            return null;
147	        }
148	        return switch (formatLocality(owner)) {
149	            case "NSW" -> "Australia/Sydney";
150	            case "VIC" -> "Australia/Melbourne";
151	            case "QLD" -> "Australia/Brisbane";
152	            default -> null;
153	        };
154	    }
155	
156	    /**
157	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
158	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
159	     * no known range, signalling that the caller should fall back to the city-to-region table.
160	     */
161	    private String regionForPostcode(String postcode) {
162	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
163	            return null;
164	        }
165	        int value = Integer.parseInt(postcode);
166	        if (value >= 2000 && value <= 2099) {
167	            return "NSW";
168	        }
169	        if (value >= 3000 && value <= 3099) {
170	            return "VIC";
171	        }
172	        if (value >= 4000 && value <= 4099) {
173	            return "QLD";
174	        }
175	        return null;
176	    }
177	
178	    /**
179	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
180	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
181	     * owner's tenure exceeds 365 days.
182	     */
183	    default Integer formatMembershipPoints(Owner owner) {
184	        if (owner == null) {
185	            return null;
186	        }
187	        int points = 0;
188	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
189	        if (hasEmail) {
190	            points += 2;
191	        }
192	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
193	        if (unique) {
194	            points += 1;
195	        }
196	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
197	        if (largeHousehold) {
198	            points += 2;
199	        }
200	        boolean tenured = owner.getRegistrationDate() != null
201	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
202	        if (tenured) {
203	            points += 3;
204	        }
205	        return points;
206	    }
207	
208	    /**
209	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
210	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
211	     */
212	    default Integer formatMembershipLevel(Owner owner) {
213	        if (owner == null) {
214	            return null;
215	        }
216	        int points = formatMembershipPoints(owner);
217	        if (points <= 1) {
218	            return 1;
219	        }
220	        if (points <= 3) {
221	            return 2;
222	        }
223	        if (points <= 5) {
224	            return 3;
225	        }
226	        return 4;
227	    }
228	
229	    /**
230	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the two-digit FY segment carried
231	     * inside the memberId ({@code '<REGION><FY><HASH8><CHK>'}): the last two digits of the starting
232	     * calendar year of the fiscal year (starting 1 July) of the business-day-adjusted registration
233	     * date (e.g. a memberId formed on 5 August 2026 yields {@code "FY26"} and one on 3 March 2026
234	     * yields {@code "FY25"}). Returns {@code null} when the memberId is absent.
235	     */
236	    default String formatFiscalYear(Owner owner) {
