249	    /**
250	     * Derive the stable, shared household identifier for owners in the same household: the first 12
251	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
252	     * so every owner with the same last name and postcode resolves to the same value regardless of
253	     * the order in which they were created.
254	     */
255	    private static String householdId(String lastNameKey, String postcode) {
256	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
257	    }
