259	    /**
260	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
261	     * name and postcode). An owner without a postcode has no household peers and counts as a household
262	     * of one.
263	     */
264	    private int householdSize(Owner owner) {
265	        if (owner.getPostcode() == null) {
266	            return 1;
267	        }
268	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
269	        return (int) this.clinicService.findAllOwners().stream()
270	            .filter(existing -> existing.getPostcode() != null
271	                && householdId.equals(
272	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
273	            .count();
274	    }
