276	    /**
277	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
278	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
279	     * postcode has no household peers, so this is empty.
280	     */
281	    private List<Owner> otherHouseholdMembers(Owner owner) {
282	        if (owner.getPostcode() == null) {
283	            return List.of();
284	        }
285	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
286	        return this.clinicService.findAllOwners().stream()
287	            .filter(existing -> !existing.isDeleted())
288	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
289	            .filter(existing -> existing.getPostcode() != null
290	                && householdId.equals(
291	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
292	            .toList();
293	    }
