295	    /**
296	     * The owner's membership level after applying the household ceiling: the natural level derived
297	     * from the owner's membership points, capped at one above the current maximum membership level
298	     * among the owner's existing household members. With no existing household member no cap applies.
299	     * Assumes the owner's household size has already been populated.
300	     */
301	    private Integer cappedMembershipLevel(Owner owner) {
302	        Integer natural = ownerMapper.formatMembershipLevel(owner);
303	        if (natural == null) {
304	            return null;
305	        }
306	        List<Owner> members = otherHouseholdMembers(owner);
307	        if (members.isEmpty()) {
308	            return natural;
309	        }
310	        int maxMemberLevel = 0;
311	        for (Owner member : members) {
312	            member.setHouseholdSize(householdSize(member));
313	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
314	            if (memberLevel != null) {
315	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
316	            }
317	        }
318	        return Math.min(natural, maxMemberLevel + 1);
319	    }
