321	    /**
322	     * Build the unified member id for a new owner as {@code '<REGION><FY><HASH8><CHK>'}, where REGION is
323	     * the region code derived from the postcode (falling back to the city-to-region table, else
324	     * {@code "UNKNOWN"}), FY is the two-digit fiscal year (starting 1 July) of the
325	     * business-day-adjusted {@code registrationDate}, HASH8 is the first 8 upper-case hex characters of
326	     * the SHA-256 digest over {@code normalizedTelephone + lastName}, and CHK is a single Luhn check
327	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id depends only on the
328	     * owner's own region, fiscal year and identity, not on how many owners already exist.
329	     */
330	    private String nextMemberId(String region, LocalDate registrationDate,
331	                                String normalizedTelephone, String lastName) {
332	        String fiscalYear = String.format("%02d", fiscalYearStart(registrationDate) % 100);
333	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
334	        String base = region + fiscalYear + hash8;
335	        return base + luhnCheckDigit(base);
336	    }
337	
338	    /**
339	     * De-duplicate a computed member id against the ids already assigned to existing owners: when
340	     * {@code memberId} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
341	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
342	     */
343	    private String deduplicateMemberId(String memberId) {
344	        Set<String> existing = this.clinicService.findAllOwners().stream()
345	            .map(Owner::getMemberId)
346	            .filter(Objects::nonNull)
347	            .collect(Collectors.toSet());
348	        if (!existing.contains(memberId)) {
349	            return memberId;
350	        }
351	        int n = 2;
352	        while (existing.contains(memberId + "-" + n)) {
353	            n++;
354	        }
355	        return memberId + "-" + n;
356	    }
357	
358	    /**
359	     * The starting calendar year of the fiscal year (which starts on 1 July) that contains the given
360	     * date: the date's own year when it falls on or after 1 July, otherwise the previous year.
361	     */
362	    private static int fiscalYearStart(LocalDate date) {
363	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
364	    }
365	
366	    /**
367	     * A single Luhn check digit (0-9) computed over the digits contained in {@code input}
368	     * (non-digit characters are ignored).
369	     */
370	    private static int luhnCheckDigit(String input) {
371	        int sum = 0;
372	        boolean dbl = true;
373	        for (int i = input.length() - 1; i >= 0; i--) {
374	            char c = input.charAt(i);
375	            if (c < '0' || c > '9') {
376	                continue;
377	            }
378	            int d = c - '0';
379	            if (dbl) {
380	                d *= 2;
381	                if (d > 9) {
382	                    d -= 9;
383	                }
384	            }
385	            sum += d;
386	            dbl = !dbl;
387	        }
388	        return (10 - (sum % 10)) % 10;
389	    }
390	
391	    /**
392	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
393	     */
394	    private static String hash8(String input) {
395	        return hashHex(input, 8, true);
396	    }
397	
398	    /**
399	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
400	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
401	     */
402	    private static String hashHex(String input, int length, boolean upperCase) {
403	        try {
404	            byte[] digest = MessageDigest.getInstance("SHA-256")
405	                .digest(input.getBytes(StandardCharsets.UTF_8));
406	            StringBuilder sb = new StringBuilder(digest.length * 2);
407	            for (byte b : digest) {
408	                sb.append(String.format("%02x", b));
409	            }
410	            String hex = sb.substring(0, length);
411	            return upperCase ? hex.toUpperCase() : hex;
412	        }
413	        catch (java.security.NoSuchAlgorithmException e) {
414	            throw new IllegalStateException(e);
415	        }
416	    }
