418	    /**
419	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
420	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
421	     * fixed city-to-region table, else {@code "UNKNOWN"}.
422	     */
423	    private static String region(String postcode, String city) {
424	        String fromPostcode = regionForPostcode(postcode);
425	        return fromPostcode != null ? fromPostcode : regionForCity(city);
426	    }
