428	    /**
429	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
430	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
431	     */
432	    private static String regionForPostcode(String postcode) {
433	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
434	            return null;
435	        }
436	        int value = Integer.parseInt(postcode);
437	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
438	            int[] range = entry.getValue();
439	            if (value >= range[0] && value <= range[1]) {
440	                return entry.getKey();
441	            }
442	        }
443	        return null;
444	    }
