446	    /**
447	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
448	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
449	     * weekday; ordinary weekday dates are returned unchanged.
450	     */
451	    static LocalDate toBusinessDay(LocalDate date) {
452	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
453	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
454	            || PUBLIC_HOLIDAYS.contains(date)) {
455	            date = date.plusDays(1);
456	        }
457	        return date;
458	    }
