474	    /**
475	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
476	     * postcode against the owner's city region.
477	     */
478	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
479	        "NSW", new int[] {2000, 2099},
480	        "VIC", new int[] {3000, 3099},
481	        "QLD", new int[] {4000, 4099});
482	
483	    /**
484	     * Resolve an owner's region from the city using the fixed city-to-region table
485	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
486	     * when the city is not listed.
487	     */
488	    private static String regionForCity(String city) {
489	        return switch (city == null ? "" : city) {
490	            case "Sydney" -> "NSW";
491	            case "Melbourne" -> "VIC";
492	            case "Brisbane" -> "QLD";
493	            default -> "UNKNOWN";
494	        };
495	    }
