497	    /**
498	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
499	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
500	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
501	     */
502	    private static boolean isPostcodeValid(String postcode, String city) {
503	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
504	            return false;
505	        }
506	        int[] range = REGION_POSTCODES.get(regionForCity(city));
507	        if (range == null) {
508	            return true;
509	        }
510	        int value = Integer.parseInt(postcode);
511	        return value >= range[0] && value <= range[1];
512	    }
