514	    /**
515	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
516	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
517	     */
518	    private static boolean isDisposableEmailDomain(String email) {
519	        if (email == null) {
520	            return false;
521	        }
522	        int at = email.lastIndexOf('@');
523	        if (at < 0 || at == email.length() - 1) {
524	            return false;
525	        }
526	        String domain = email.substring(at + 1).toLowerCase();
527	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
528	    }
