530	    /**
531	     * Whether the owner's city is approaching the per-city capacity limit of 50 owners: true when the
532	     * city already holds between 40 and 49 owners (counted the same way as the hard-limit rule, over
533	     * all owners with a matching, normalized city), otherwise false.
534	     */
535	    private boolean capacityWarning(String city) {
536	        String cityKey = normaliseIdentity(city);
537	        long ownersInCity = this.clinicService.findAllOwners().stream()
538	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
539	            .count();
540	        return ownersInCity >= 40 && ownersInCity <= 49;
541	    }
