543	    /**
544	     * The soft, review-triggering per-city capacity threshold (as opposed to the hard 50-owner limit
545	     * that rejects a create): a city holding this many owners or more is considered over soft capacity.
546	     */
547	    private static final int SOFT_CITY_CAPACITY = 40;
548	
549	    /**
550	     * Whether the owner's city is over its soft capacity: true when the city already holds
551	     * {@link #SOFT_CITY_CAPACITY} owners or more (counted the same way as the hard-limit rule, over all
552	     * owners with a matching, normalized city), otherwise false.
553	     */
554	    private boolean overSoftCityCapacity(String city) {
555	        String cityKey = normaliseIdentity(city);
556	        long ownersInCity = this.clinicService.findAllOwners().stream()
557	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
558	            .count();
559	        return ownersInCity >= SOFT_CITY_CAPACITY;
560	    }
561	
562	    /**
563	     * Whether the email's domain (the part after the final '@') is disposable-adjacent: it is one of
564	     * the disposable domains, or a subdomain of one (it ends with {@code '.<disposableDomain>'}). This
565	     * is broader than {@link #isDisposableEmailDomain(String)} (which rejects an exact disposable
566	     * domain at create time): an owner whose stored email sits just off the blocklist is flagged for
567	     * review rather than rejected. A {@code null} email is not disposable-adjacent; the comparison is
568	     * case-insensitive.
569	     */
570	    private static boolean isDisposableAdjacentEmailDomain(String email) {
571	        if (email == null) {
572	            return false;
573	        }
574	        int at = email.lastIndexOf('@');
575	        if (at < 0 || at == email.length() - 1) {
576	            return false;
577	        }
578	        String domain = email.substring(at + 1).toLowerCase();
579	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
580	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
581	                return true;
582	            }
583	        }
584	        return false;
585	    }
