587	    /**
588	     * The owner's risk flag: true when any of these hold — the owner is a possible duplicate
589	     * (a {@code possibleDuplicateOf} target exists), the email domain is disposable-adjacent, or the
590	     * owner's city is over its soft capacity; otherwise false.
591	     */
592	    private boolean riskFlag(Owner owner) {
593	        return owner.getPossibleDuplicateOf() != null
594	            || isDisposableAdjacentEmailDomain(owner.getEmail())
595	            || overSoftCityCapacity(owner.getCity());
596	    }
