614	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
615	    @Override
616	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
617	        Owner owner = this.clinicService.findOwnerById(ownerId);
618	        if (owner == null) {
619	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
620	        }
621	        owner.setHouseholdSize(householdSize(owner));
622	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
623	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
624	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
625	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
626	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
627	        ownerDto.setRiskFlag(riskFlag(owner));
628	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
629	    }
630	
631	    /**
632	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
633	     * request carries no such header (or there is no active servlet request). A blank value is treated
634	     * as absent.
635	     */
636	    private static String currentIdempotencyKey() {
637	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
638	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
639	            return null;
640	        }
641	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
642	        return (key == null || key.isBlank()) ? null : key;
643	    }
644	
645	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
646	    @Override
647	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
648	        String idempotencyKey = currentIdempotencyKey();
649	        if (idempotencyKey != null) {
650	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
651	            if (existingId != null) {
652	                Owner existing = this.clinicService.findOwnerById(existingId);
653	                if (existing != null) {
654	                    existing.setHouseholdSize(householdSize(existing));
655	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
656	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
657	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
658	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
659	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
660	                    existingDto.setRiskFlag(riskFlag(existing));
661	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
662	                }
663	            }
664	        }
665	        String telephone = toE164(ownerFieldsDto.getTelephone());
666	        if (telephone == null) {
667	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied telephone number is not valid");
668	        }
669	        String email = ownerFieldsDto.getEmail();
670	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
671	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied email address is not valid");
672	        }
673	        if (isDisposableEmailDomain(email)) {
674	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Disposable email addresses are not accepted");
675	        }
676	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
677	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
678	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
679	        // normalized addressLine2 appended after a single space when present.
680	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
681	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
682	        boolean structuredAddress = !addressLine1.isEmpty();
683	        String address;
684	        if (structuredAddress) {
685	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
686	        } else {
687	            address = normaliseAddress(ownerFieldsDto.getAddress());
688	        }
689	        if (address.isEmpty()) {
690	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An address is required");
691	        }
692	        String postcode = ownerFieldsDto.getPostcode();
693	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
694	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied postcode is not valid for the city");
695	        }
696	        if (ownerFieldsDto.getRegistrationDate() != null
697	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
698	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The registration date cannot be in the future");
699	        }
700	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
701	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
702	        LocalDate registrationDate = toBusinessDay(effectiveDate);
703	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
704	            .map(Owner::getRegistrationDate)
705	            .filter(existing -> existing != null)
706	            .map(OwnerRestControllerV1::toBusinessDay)
707	            .filter(registrationDate::equals)
708	            .count();
709	        if (ownersCreatedThatDay >= 100) {
710	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
711	                "The daily owner-registration limit has been reached");
712	        }
713	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
714	        long ownersInCity = this.clinicService.findAllOwners().stream()
715	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
716	            .count();
717	        if (ownersInCity >= 50) {
718	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The city has reached its owner capacity");
719	        }
720	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
721	        // The household is deterministically keyed on (normalized last name, postcode): every owner
722	        // with a postcode belongs to the household identified by this computed id, and owners sharing
723	        // a last name and postcode share it automatically. A new owner may join an existing household;
724	        // the household ceiling below (rather than a hard rejection) governs its membership level.
725	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
726	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
727	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
728	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
729	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
730	        boolean identityInUse = this.clinicService.findAllOwners().stream()
731	            .filter(existing -> !existing.isDeleted())
732	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
733	                existing.getEmail(), existing.getLastName()).equals(identityKey));
734	        if (identityInUse) {
735	            throw new ResponseStatusException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
736	        }
737	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
738	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
739	        // duplicate, but the new owner is flagged as a possible duplicate of it.
740	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
741	        Integer possibleDuplicateOf = (postcode == null) ? null
742	            : this.clinicService.findAllOwners().stream()
743	                .filter(existing -> !existing.isDeleted())
744	                .filter(existing -> postcode.equals(existing.getPostcode()))
745	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
746	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
747	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
748	                .map(Owner::getId)
749	                .findFirst()
750	                .orElse(null);
751	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
752	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
753	            .filter(existing ->
754	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
755	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
756	            .count();
757	        HttpHeaders headers = new HttpHeaders();
758	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
759	        owner.setNamesakeCount(namesakeCount);
760	        owner.setAddress(address);
761	        if (structuredAddress) {
762	            owner.setAddressLine1(addressLine1);
763	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
764	        } else {
765	            owner.setAddressLine1(null);
766	            owner.setAddressLine2(null);
767	        }
768	        owner.setTelephone(telephone);
769	        owner.setEmail(email == null ? null : email.toLowerCase());
770	        owner.setRegistrationDate(registrationDate);
771	        owner.setMemberId(deduplicateMemberId(nextMemberId(
772	            region(postcode, owner.getCity()), registrationDate, telephone, owner.getLastName())));
773	        owner.setHouseholdId(householdId);
774	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
775	        this.clinicService.saveOwner(owner);
776	        if (idempotencyKey != null) {
777	            this.idempotentCreations.put(idempotencyKey, owner.getId());
778	        }
779	        owner.setHouseholdSize(householdSize(owner));
780	        Integer membershipLevel = cappedMembershipLevel(owner);
781	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
782	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
783	        // Immutable structured event carrying the owner's current primary identifier (the
784	        // unified memberId), with a monotonic sequence.
785	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
786	            owner.getMemberId(), membershipLevel).toJson());
787	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
788	        NOTIFY.info("welcome notification: ownerId={} memberId={}",
789	            owner.getId(), owner.getMemberId());
790	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
791	        ownerDto.setMembershipLevel(membershipLevel);
792	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
793	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
794	        ownerDto.setRiskFlag(riskFlag(owner));
795	        headers.setLocation(UriComponentsBuilder.newInstance()
796	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
797	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
798	    }
799	
800	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
801	    @Override
802	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
803	        String telephone = toE164(ownerFieldsDto.getTelephone());
804	        if (telephone == null) {
805	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied telephone number is not valid");
806	        }
