814	        }
815	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
816	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
817	        if (!addressLine1.isEmpty()) {
818	            currentOwner.setAddressLine1(addressLine1);
819	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
820	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
821	        } else {
822	            currentOwner.setAddressLine1(null);
823	            currentOwner.setAddressLine2(null);
824	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
825	        }
826	        currentOwner.setCity(ownerFieldsDto.getCity());
827	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
828	        currentOwner.setLastName(ownerFieldsDto.getLastName());
829	        currentOwner.setTelephone(telephone);
830	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
831	        this.clinicService.saveOwner(currentOwner);
832	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
833	    }
834	
