        }
        return "/api/owners/" + owner.getId();
    }

    /**
     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
     */
    default String formatDisplayName(Owner owner) {
        if (owner == null) {
            return null;
        }
        return owner.getLastName() + ", " + owner.getFirstName();
    }

